-- Allocation/receipt operations are RPC-owned immutable evidence.  Every
-- public function delegates with a fixed search path and locks its aggregate.
create table public.factory_receipt_requests (
  id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade,
  receipt_request_id text not null, payload_hash text not null, factory_arrival_id bigint not null,
  immutable_payload jsonb not null, receipt_event_id bigint, created_at timestamptz not null default timezone('utc',now()),
  unique(user_id,receipt_request_id), unique(id,user_id), foreign key(factory_arrival_id,user_id) references public.factory_arrivals(id,user_id) on delete restrict
);
create table public.factory_arrival_shortage_closures (
  id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade,
  factory_arrival_allocation_id bigint not null, quantity integer not null check(quantity>0), reason text not null check(btrim(reason)<>''), closed_at timestamptz not null default timezone('utc',now()),
  unique(id,user_id), foreign key(factory_arrival_allocation_id,user_id) references public.factory_arrival_allocations(id,user_id) on delete restrict
);
create table public.factory_receipt_line_corrections (
  id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade,
  correction_request_id text not null, factory_receipt_line_id bigint not null, reason text not null check(btrim(reason)<>''), transaction_id bigint, created_at timestamptz not null default timezone('utc',now()),
  unique(user_id,correction_request_id), unique(factory_receipt_line_id), unique(id,user_id), foreign key(factory_receipt_line_id,user_id) references public.factory_receipt_lines(id,user_id) on delete restrict
);
alter table public.factory_receipt_events add column if not exists receipt_request_id text;
alter table public.factory_receipt_lines add column if not exists factory_arrival_item_id bigint, add column if not exists warehouse_id bigint, add column if not exists normal_quantity integer not null default 0 check(normal_quantity>=0), add column if not exists overage_quantity integer not null default 0 check(overage_quantity>=0), add constraint factory_receipt_lines_quantity_kind_check check(normal_quantity + overage_quantity > 0);
alter table public.factory_receipt_lines add constraint factory_receipt_lines_item_user_fkey foreign key(factory_arrival_item_id,user_id) references public.factory_arrival_items(id,user_id) on delete restrict;
alter table public.factory_receipt_lines add constraint factory_receipt_lines_warehouse_user_fkey foreign key(warehouse_id,user_id) references public.warehouses(id,user_id) on delete restrict;
create index factory_receipt_requests_arrival_idx on public.factory_receipt_requests(user_id,factory_arrival_id);
create index factory_shortage_closures_allocation_idx on public.factory_arrival_shortage_closures(user_id,factory_arrival_allocation_id);

create or replace function private.refresh_factory_arrival_status(p_arrival_id bigint,p_user_id uuid) returns void language plpgsql set search_path=private,public as $$
begin
 update public.factory_arrivals a set status=case
  when exists(select 1 from public.factory_arrival_allocations x where x.factory_arrival_id=a.id and x.user_id=p_user_id and x.normally_received_quantity+x.shortage_closed_quantity<x.allocated_quantity)
   then case when exists(select 1 from public.factory_receipt_lines l join public.factory_receipt_events e on e.id=l.factory_receipt_event_id and e.user_id=l.user_id where e.factory_arrival_id=a.id and l.user_id=p_user_id) then 'PARTIAL' else 'READY' end
  when exists(select 1 from public.factory_arrival_shortage_closures c join public.factory_arrival_allocations x on x.id=c.factory_arrival_allocation_id and x.user_id=c.user_id where x.factory_arrival_id=a.id and c.user_id=p_user_id) then 'VARIANCE_CLOSED'
  else 'RECEIVED' end,updated_at=timezone('utc',now()) where a.id=p_arrival_id and a.user_id=p_user_id;
end $$;
create or replace function private.enqueue_factory_variant(p_user_id uuid,p_variant_id bigint) returns void language plpgsql set search_path=private,public as $$
declare v_on_hand integer; v_committed integer; v_target integer; r record; begin
 select coalesce(sum(i.quantity),0) into v_on_hand from public.inventory i join public.product_variants v on v.model_id=i.model_id and v.size_id=i.size_id and v.color_id=i.color_id and v.user_id=i.user_id where v.id=p_variant_id and i.user_id=p_user_id;
 select coalesce(sum(quantity),0) into v_committed from public.inventory_reservations where user_id=p_user_id and product_variant_id=p_variant_id and status='active'; v_target:=greatest(0,v_on_hand-v_committed);
 for r in select id from public.channel_product_refs where user_id=p_user_id and variant_id=p_variant_id loop
  insert into public.inventory_sync_outbox(user_id,channel_product_ref_id,target_quantity,status,last_error,requested_at,updated_at) values(p_user_id,r.id,v_target,'required','동기화 필요: 현재 provider는 재고 수량 쓰기를 지원하지 않습니다.',timezone('utc',now()),timezone('utc',now())) on conflict(user_id,channel_product_ref_id) do update set target_quantity=excluded.target_quantity,status='required',last_error=excluded.last_error,requested_at=excluded.requested_at,updated_at=excluded.updated_at;
 end loop; end $$;
create or replace function public.replace_factory_arrival_allocations(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=private,public as $$
declare u uuid:=auth.uid(); a public.factory_arrivals%rowtype; i public.factory_arrival_items%rowtype; r jsonb; total integer:=0; seen bigint[]:='{}'; w public.warehouses%rowtype; begin
 if u is null then raise exception 'Authentication is required.'; end if; select * into a from public.factory_arrivals where id=(p_payload->>'arrival_id')::bigint and user_id=u for update; if not found or a.status in('RECEIVED','VARIANCE_CLOSED','CANCELLED') then raise exception 'Arrival cannot be reallocated.'; end if;
 select * into i from public.factory_arrival_items where id=(p_payload->>'item_id')::bigint and factory_arrival_id=a.id and user_id=u for update; if not found then raise exception 'Arrival item not found.'; end if;
 if exists(select 1 from public.factory_arrival_allocations where factory_arrival_item_id=i.id and user_id=u and (normally_received_quantity>0 or shortage_closed_quantity>0)) then raise exception 'Received or closed allocation cannot be moved.'; end if;
 for r in select value from jsonb_array_elements(p_payload->'allocations') loop if (r->>'warehouse_id')::bigint=any(seen) or coalesce((r->>'quantity')::integer,0)<=0 then raise exception 'Invalid allocation split.'; end if; select * into w from public.warehouses where id=(r->>'warehouse_id')::bigint and user_id=u; if not found then raise exception 'Warehouse not found.'; end if; seen:=array_append(seen,w.id); total:=total+(r->>'quantity')::integer; end loop;
 if total<>i.ordered_quantity then raise exception 'Allocation total must equal ordered quantity.'; end if; delete from public.factory_arrival_allocations where factory_arrival_item_id=i.id and user_id=u; for r in select value from jsonb_array_elements(p_payload->'allocations') loop insert into public.factory_arrival_allocations(user_id,factory_arrival_id,factory_arrival_item_id,product_variant_id,warehouse_id,allocated_quantity,warehouse_name_snapshot) values(u,a.id,i.id,i.product_variant_id,(r->>'warehouse_id')::bigint,(r->>'quantity')::integer,(select name from public.warehouses where id=(r->>'warehouse_id')::bigint and user_id=u)); end loop; perform private.refresh_factory_arrival_status(a.id,u); return jsonb_build_object('arrival_id',a.id); end $$;
create or replace function public.close_factory_arrival_shortage(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=private,public as $$
declare u uuid:=auth.uid(); x public.factory_arrival_allocations%rowtype; q integer:=(p_payload->>'quantity')::integer; begin if u is null or q is null or q<=0 or btrim(coalesce(p_payload->>'reason',''))='' then raise exception 'Invalid shortage closure.'; end if; select * into x from public.factory_arrival_allocations where id=(p_payload->>'allocation_id')::bigint and user_id=u for update; if not found or q>x.allocated_quantity-x.normally_received_quantity-x.shortage_closed_quantity then raise exception 'Shortage exceeds expected remainder.'; end if; insert into public.factory_arrival_shortage_closures(user_id,factory_arrival_allocation_id,quantity,reason) values(u,x.id,q,btrim(p_payload->>'reason')); update public.factory_arrival_allocations set shortage_closed_quantity=shortage_closed_quantity+q,updated_at=timezone('utc',now()) where id=x.id; perform private.refresh_factory_arrival_status(x.factory_arrival_id,u); return jsonb_build_object('allocation_id',x.id); end $$;
revoke insert,update,delete on public.factory_receipt_requests,public.factory_arrival_shortage_closures,public.factory_receipt_line_corrections,public.factory_receipt_events,public.factory_receipt_lines from authenticated;
grant execute on function public.replace_factory_arrival_allocations(jsonb),public.close_factory_arrival_shortage(jsonb) to authenticated;

-- Request/correction entry points deliberately share the payload-shaped public
-- API. Their detailed receipt evidence remains append-only.
create or replace function public.receive_factory_arrival_request(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=private,public as $$
declare u uuid:=auth.uid(); request_id text:=btrim(p_payload->>'receipt_request_id'); hash text:=p_payload->>'payload_hash'; existing public.factory_receipt_requests%rowtype; a public.factory_arrivals%rowtype; line jsonb; x public.factory_arrival_allocations%rowtype; i public.factory_arrival_items%rowtype; v public.product_variants%rowtype; q integer; oq integer; event_id bigint; tx bigint; begin
 if u is null or request_id='' or hash !~ '^[0-9a-f]{64}$' or jsonb_typeof(p_payload->'lines')<>'array' then raise exception 'Invalid receipt request.'; end if;
 select * into existing from public.factory_receipt_requests where user_id=u and receipt_request_id=request_id for update; if found then if existing.payload_hash<>hash then raise exception 'receipt_request_conflict'; end if; return jsonb_build_object('receipt_event_id',existing.receipt_event_id,'idempotent',true); end if;
 select * into a from public.factory_arrivals where id=(p_payload->>'arrival_id')::bigint and user_id=u for update; if not found or a.status in('RECEIVED','VARIANCE_CLOSED','CANCELLED') then raise exception 'Arrival cannot be received.'; end if;
 -- Validate all rows before any inventory/evidence write.
 for line in select value from jsonb_array_elements(p_payload->'lines') loop q:=coalesce((line->>'quantity')::integer,0); oq:=coalesce((line->>'overage_quantity')::integer,0); select * into x from public.factory_arrival_allocations where id=(line->>'allocation_id')::bigint and factory_arrival_id=a.id and user_id=u for update; if not found or q<0 or oq<0 or (q=0 and oq=0) or q>x.allocated_quantity-x.normally_received_quantity-x.shortage_closed_quantity then raise exception 'Invalid receipt line.'; end if; end loop;
 insert into public.factory_receipt_events(user_id,factory_arrival_id,event_kind,received_at,immutable_payload,receipt_request_id) values(u,a.id,'RECEIPT',timezone('utc',now()),p_payload,request_id) returning id into event_id;
 insert into public.factory_receipt_requests(user_id,receipt_request_id,payload_hash,factory_arrival_id,immutable_payload,receipt_event_id) values(u,request_id,hash,a.id,p_payload,event_id);
 for line in select value from jsonb_array_elements(p_payload->'lines') loop q:=coalesce((line->>'quantity')::integer,0); oq:=coalesce((line->>'overage_quantity')::integer,0); select * into x from public.factory_arrival_allocations where id=(line->>'allocation_id')::bigint and user_id=u for update; select * into i from public.factory_arrival_items where id=x.factory_arrival_item_id and user_id=u; select * into v from public.product_variants where id=x.product_variant_id and user_id=u; insert into public.inventory(user_id,model_id,size_id,color_id,warehouse_id,quantity) values(u,v.model_id,v.size_id,v.color_id,x.warehouse_id,q+oq) on conflict(user_id,model_id,size_id,color_id,warehouse_id) do update set quantity=public.inventory.quantity+excluded.quantity,updated_at=timezone('utc',now()); insert into public.transactions(user_id,date,model_id,size_id,color_id,type,quantity,warehouse_id,source_channel,reference_type,reference_id,memo) values(u,current_date,v.model_id,v.size_id,v.color_id,'INBOUND',q+oq,x.warehouse_id,'factory-arrival','factory_receipt_event',event_id,case when oq>0 then btrim(coalesce(line->>'overage_reason','초과 입고')) else '검수 입고' end) returning id into tx; insert into public.factory_receipt_lines(user_id,factory_receipt_event_id,factory_arrival_allocation_id,factory_arrival_item_id,warehouse_id,transaction_id,received_quantity,normal_quantity,overage_quantity,seller_sku_snapshot,product_name_snapshot,option_name_snapshot,warehouse_name_snapshot) values(u,event_id,x.id,i.id,x.warehouse_id,tx,q+oq,q,oq,i.seller_sku_snapshot,i.product_name_snapshot,i.option_name_snapshot,x.warehouse_name_snapshot); update public.factory_arrival_allocations set normally_received_quantity=normally_received_quantity+q,updated_at=timezone('utc',now()) where id=x.id; update public.factory_arrival_items set received_quantity=received_quantity+q,updated_at=timezone('utc',now()) where id=i.id; perform private.enqueue_factory_variant(u,v.id); end loop; perform private.refresh_factory_arrival_status(a.id,u); return jsonb_build_object('receipt_event_id',event_id,'idempotent',false); end $$;
create or replace function public.record_factory_arrival_follow_up(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=private,public as $$ begin raise exception 'Follow-up receipt requires the dedicated receipt-line linkage implementation.'; end $$;
create or replace function public.reverse_factory_receipt_line(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=private,public as $$ begin raise exception 'Receipt correction requires the dedicated correction linkage implementation.'; end $$;
grant execute on function public.receive_factory_arrival_request(jsonb),public.record_factory_arrival_follow_up(jsonb),public.reverse_factory_receipt_line(jsonb) to authenticated;
